import json,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]; C=json.loads((R/'content.json').read_text())
def e(s):return html.escape(str(s),quote=True)
def url(p,l):return ('fa' if p=='home' and l=='fa' else 'index' if p=='home' else p+('-fa' if l=='fa' else ''))+'.html'
def link(p,t,l,cls=''):return f'<a class="{cls}" href="{url(p,l)}">{e(t)}</a>'
def section(title,text='',body=''):return f'<section class="section wrap"><div class="section-head"><h2>{e(title)}</h2><p>{e(text)}</p></div>{body}</section>'
def rows(items):return '<div class="rows">'+''.join(f'<article class="row"><span class="number">{i+1:02}</span><h3>{e(x[0])}</h3><div><p>{e(x[1])}</p>'+ ('<ul>'+''.join('<li>'+e(y)+'</li>' for y in x[2])+'</ul>' if len(x)>2 else '')+'</div></article>' for i,x in enumerate(items))+'</div>'
def render(p,l):
 d=C[l]; fa=l=='fa'; T=lambda en,fa_:fa_ if fa else en
 cta=T('Book a free consultation','درخواست مشاوره رایگان')
 nav=''.join(link(k,d['pages'][k],l,'active' if p==k else '') for k in ['services','approach','pathways','about'])
 out=f'''<!doctype html><html lang="{l}" dir="{'rtl' if fa else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(d['pages'][p])} | Vellum House</title><meta name="description" content="{e(d['description'])}"><meta name="theme-color" content="#f8f7f3"><meta property="og:title" content="{e(d['pages'][p])} | Vellum House"><meta property="og:description" content="{e(d['description'])}"><meta property="og:type" content="website"><link rel="alternate" hreflang="en" href="{url(p,'en')}"><link rel="alternate" hreflang="fa" href="{url(p,'fa')}"><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/config.js"></script><script defer src="assets/main.js"></script></head><body><a class="skip" href="#main">{e(d['skip'])}</a><header><div class="wrap nav"><a class="brand" href="{url('home',l)}" aria-label="Vellum House"><img src="assets/logo-mark.svg" width="44" height="44" alt=""><span>VELLUM HOUSE<small>{e(d['tag'])}</small></span></a><button id="menu" aria-expanded="false" aria-controls="navigation">{e(d['menu'])} ☰</button><nav id="navigation" aria-label="{e(d['navLabel'])}">{nav}<a class="language" href="{url(p,'en' if fa else 'fa')}" lang="{'en' if fa else 'fa'}">{'English' if fa else 'فارسی'}</a>{link('contact',cta,l,'button small')}</nav></div></header><main id="main">'''
 if p=='home':
  out+=f'''<section class="hero wrap"><div><p class="eyebrow">{e(d['heroK'])}</p><h1>{T('A clearer path.<br>A considered future.','مسیر روشن‌تر<br>آینده‌ای سنجیده‌تر')}</h1><p class="hero-text">{T('Personal academic planning, online teaching and ongoing guidance. One coordinated plan for school, university and what comes next.','برنامه‌ریزی اختصاصی، آموزش آنلاین و همراهی مستمر؛ همه در یک مسیر هماهنگ، از مدرسه تا دانشگاه و تحصیلات تکمیلی.')}</p><div class="actions">{link('contact',cta,l,'button')}{link('services',T('Explore our services ↗','آشنایی با خدمات ما'),l,'text-link')}</div><p class="micro">{T('Free initial consultation · Online support · Individual planning','جلسه آشنایی رایگان · آموزش آنلاین · برنامه اختصاصی')}</p></div><aside class="hero-note"><span class="eyebrow">{T('YOUR EDUCATION, CONNECTED','همراهی در مسیر تحصیل')}</span><div class="editorial-mark" aria-hidden="true"><img src="assets/logo-mark.svg" alt="" width="130" height="130"></div><p>{T('The right priorities.<br>The right support.<br>A plan that moves with you.','اولویت‌های روشن<br>آموزش متناسب با نیاز شما<br>برنامه‌ای همگام با پیشرفت شما')}</p><span class="note-bottom">VELLUM HOUSE / {T('A PERSONAL APPROACH','نگاهی فردمحور')}</span></aside></section>'''
  out+='<div class="trust-strip wrap">'+''.join('<span>'+e(x)+'</span>' for x in d['principles'])+'</div>'
  out+=section(T('An education with every part connected.','همه بخش‌های تحصیل، در یک مسیر هماهنگ.'),d['introText'])
  out+=section(d['servicesTitle'],T('Start with what you need now. Build towards what matters next.','از نیاز امروز شروع می‌کنیم و برای هدف‌های بعدی برنامه می‌ریزیم.'),rows(d['serviceCards'][:3])+link('services',d['allServices'],l,'text-link below'))
  out+=section(T('Support for your stage.','همراهی متناسب با مرحله‌ای که در آن هستید.'),'','<div class="path-grid">'+''.join(f'<a href="{url("pathways",l)}#path-{i}" class="path"><span class="eyebrow">0{i+1}</span><h3>{e(x[0])}</h3><p>{e(x[1])}</p><span aria-hidden="true">↗</span></a>' for i,x in enumerate(d['pathCards']))+'</div>')
  out+=section(T('A clear beginning.','شروعی ساده و روشن.'),'',rows([[T('Tell us what you need','از نیازتان بگویید'),T('Complete the short enquiry form. No documents or payment are needed.','فرم کوتاه درخواست را پر کنید. در این مرحله نیازی به ارسال مدارک یا پرداخت هزینه نیست.')],[T('Meet us online, free of charge','در جلسه آنلاین رایگان آشنا شویم'),T('We email you to arrange the initial consultation and send the meeting details.','برای هماهنگی جلسه مشاوره اولیه و ارسال جزئیات، از طریق ایمیل با شما تماس می‌گیریم.')],[T('Decide with a clear proposal','با شناخت تصمیم بگیرید'),T('If we are a good fit, we agree on the support, availability and fees before you commit.','اگر امکان همکاری وجود داشته باشد، خدمات، زمان‌بندی و هزینه‌ها پیش از شروع مشخص می‌شوند.')]]))
 else:
  h=d['pageHeros'][p]
  if p=='contact': h=[T('Let’s find your next step.','قدم بعدی را با هم پیدا کنیم.'),T('Start with a free online consultation. Tell us a little about your situation; we will email you to arrange a suitable time.','با یک جلسه مشاوره آنلاین رایگان شروع کنید. کمی از شرایط و نیازتان بنویسید تا برای هماهنگی زمان جلسه به شما ایمیل بزنیم.')]
  out+=f'<section class="page-hero wrap"><p class="eyebrow">{e(d["pages"][p])}</p><h1>{e(h[0])}</h1><p class="lead">{e(h[1])}</p></section>'
  if p=='services':out+=section(T('What we can help with','در چه زمینه‌هایی همراه شما هستیم'),'',rows(d['serviceCards']))+section(d['scopeTitle'],d['scopeText'],'<ul class="scope">'+''.join('<li>'+e(x)+'</li>' for x in d['scopePoints'])+'</ul>')
  elif p=='approach':out+=section(d['problemTitle'],' '.join(d['problemText']))+section(d['roadTitle'],d['roadText'],rows(d['steps']))+section(d['reportTitle'],d['reportText'],rows(d['reportRows'])+'<p class="micro">'+e(d['reportNote'])+'</p>')
  elif p=='pathways':
   for i,x in enumerate(d['pathDetails']):out+=f'<div id="path-{i}">'+section(x[0],x[1],'<ul class="scope">'+''.join('<li>'+e(y)+'</li>' for y in x[2])+'</ul>'+link('contact',cta,l,'text-link'))+'</div>'
  elif p=='about':
   out+=section(d['beliefTitle'],' '.join(d['beliefText']))+section(T('Academic direction','مدیریت و راهبری علمی'),T('Vellum House is founded by Reyhaneh Vojoudi, a physics educator and researcher with an MSc in Gravity and Cosmology. Her work across teaching, research and academic mentoring informs an approach that connects immediate learning needs with longer-term goals.','ولوم هاوس به بنیان‌گذاری ریحانه وجودی، مدرس و پژوهشگر فیزیک و دانش‌آموخته کارشناسی ارشد گرانش و کیهان‌شناسی، شکل گرفته است. تجربه او در آموزش، پژوهش و راهنمایی تحصیلی، مبنای رویکردی است که نیازهای آموزشی امروز را به هدف‌های بلندمدت پیوند می‌دهد.'),'<a class="text-link" href="https://reyhanehvojoudi.ir/">'+T('Meet the founder ↗','آشنایی بیشتر با بنیان‌گذار')+'</a>')+section(d['valuesTitle'],'',rows(d['values']))+section(T('What you can expect from us','از همکاری چه انتظاری داشته باشید'),T('A defined scope, coordinated teaching and agreed progress updates. We confirm the educators, schedule, fees and communication arrangements before support begins. Admission and scholarship decisions remain with the institutions.','دامنه خدمات مشخص، آموزش هماهنگ و گزارش پیشرفت بر اساس توافق؛ مدرس‌ها، برنامه زمانی، هزینه‌ها و شیوه ارتباط پیش از آغاز همکاری مشخص می‌شوند. تصمیم درباره پذیرش و بورسیه بر عهده مؤسسات آموزشی است.'))
  elif p=='journal':out+=section(d['brochureTitle'],d['brochureText'],'<a class="button" href="assets/Vellum_House_Brochure.pdf" download>'+e(d['download'])+'</a>')+section(T('Before your consultation','پیش از جلسه مشاوره'),T('Think about the main challenge, your nearest deadline, and what a useful change would look like. You do not need to have a complete plan; that is what the first conversation helps clarify.','به مهم‌ترین چالش فعلی، نزدیک‌ترین مهلت و تغییری که به آن نیاز دارید فکر کنید. لازم نیست از قبل برنامه کاملی داشته باشید؛ جلسه اول برای روشن شدن همین موضوع‌هاست.'))
  elif p=='contact':
   out+='<section class="wrap contact-layout section"><aside><h2>'+T('A conversation before a commitment.','پیش از تصمیم‌گیری، گفت‌وگو کنیم.')+'</h2><p>'+T('The first consultation is free. We discuss your priorities and whether our support is suitable. Any assessment, lessons or ongoing programme will be proposed separately.','جلسه مشاوره اولیه رایگان است. درباره اولویت‌های شما و امکان همکاری صحبت می‌کنیم. ارزیابی، کلاس‌ها یا برنامه مستمر در صورت نیاز، جداگانه پیشنهاد می‌شوند.')+'</p><ol class="contact-steps">'+''.join('<li>'+x+'</li>' for x in [T('Send the form.','فرم را ارسال کنید.'),T('Check your inbox and spam folder.','صندوق ورودی و پوشه اسپم ایمیلتان را بررسی کنید.'),T('We will email you to arrange the session.','برای هماهنگی جلسه به شما ایمیل می‌زنیم.')])+'</ol><p class="micro">'+T('A request does not confirm a meeting time or reserve a teaching place.','ارسال درخواست به معنای تأیید زمان جلسه یا رزرو کلاس نیست.')+'</p></aside><div class="form-panel"><form id="enquiry-form"><h2>'+T('Request your free consultation','درخواست مشاوره رایگان')+'</h2><p class="micro">'+T('All fields are required. For a school student, a parent or guardian should complete this form.','همه موارد را تکمیل کنید. برای دانش‌آموزان، لطفاً والد یا سرپرست فرم را پر کند.')+'</p><div class="form-grid">'
   fields=[('fullName',T('Full name (parent / student)','نام و نام خانوادگی والد یا متقاضی'),'text','name',120),('grade',T('Student’s grade / study level','پایه یا مقطع تحصیلی'),'text','off',100),('city',T('City','شهر'),'text','address-level2',100),('phone',T('Phone number (with country code)','شماره تماس با کد کشور'),'tel','tel',40),('email',T('Email','ایمیل'),'email','email',200)]
   for key,label,typ,auto,n in fields:out+=f'<div class="field"><label for="{key}">{label}</label><input id="{key}" name="{key}" type="{typ}" autocomplete="{auto}" maxlength="{n}" required'+(' dir="ltr"' if typ in ['email','tel'] else '')+(' minlength="6"' if typ=='tel' else '')+'></div>'
   out+='<div class="field full"><label for="message">'+T('What would you like help with?','در چه زمینه‌ای به همراهی نیاز دارید؟')+'</label><textarea id="message" name="message" rows="5" maxlength="3000" required placeholder="'+T('Your goals, current challenges, or a deadline we should know about.','از هدف‌ها، چالش‌های فعلی یا مهلت مهمی که پیش رو دارید بنویسید.')+'"></textarea></div></div><div class="honey" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input name="consent" type="checkbox" required><span>'+T('I agree to be contacted about this enquiry and have read the ','با تماس درباره این درخواست موافقم و ')+link('privacy',T('privacy notice.','توضیحات حریم خصوصی'),l)+T('',' را خوانده‌ام.')+'</span></label><button class="button" type="submit">'+T('Request a free consultation','ارسال درخواست مشاوره رایگان')+'</button><p class="micro">'+T('Please check your email after submitting. Session arrangements will be emailed to you.','پس از ارسال، ایمیلتان را بررسی کنید. هماهنگی و جزئیات جلسه از طریق ایمیل انجام می‌شود.')+'</p><p id="form-status" role="status" aria-live="polite" tabindex="-1"></p><noscript>'+T('Please enable JavaScript to send this form.','برای ارسال فرم، جاوااسکریپت مرورگر را فعال کنید.')+'</noscript></form></div></section>'
   faq=d['faq'][:5]+[[T('Is the first consultation free?','آیا جلسه اول رایگان است؟'),T('Yes. The initial online consultation is free. Any further assessment or programme is quoted separately before you agree.','بله، جلسه مشاوره آنلاین اولیه رایگان است. هزینه هرگونه ارزیابی یا برنامه بعدی، پیش از توافق جداگانه اعلام می‌شود.')]]
   out+=section(d['faqTitle'],'','<div class="faq">'+''.join('<details><summary>'+e(x[0])+'</summary><p>'+e(x[1])+'</p></details>' for x in faq)+'</div>')
  elif p=='privacy':
   items=[[T('What we collect','اطلاعاتی که دریافت می‌کنیم'),T('Your name, grade or study level, city, phone number, email and enquiry message, plus the submission time, language and a request reference. Please do not submit identity documents, payment details or confidential health information.','نام، پایه یا مقطع تحصیلی، شهر، شماره تماس، ایمیل و متن درخواست شما، همراه با زمان ارسال، زبان فرم و شناسه درخواست ثبت می‌شود. لطفاً مدارک هویتی، اطلاعات پرداخت یا اطلاعات محرمانه پزشکی ارسال نکنید.')],[T('Where your enquiry goes','درخواست شما کجا ثبت می‌شود'),T('Enquiries are stored in a private Google Sheet and emailed to reyhaneh.vojoudi@gmail.com and kasra01@gmail.com. An acknowledgement is sent to your email. Google and the website host process technical data to provide these services.','درخواست‌ها در یک فایل خصوصی Google Sheets ثبت و برای reyhaneh.vojoudi@gmail.com و kasra01@gmail.com ایمیل می‌شوند. تأیید دریافت نیز به ایمیل شما ارسال می‌شود. گوگل و میزبان سایت برای ارائه این خدمات، اطلاعات فنی لازم را پردازش می‌کنند.')],[T('How we use it','چگونه از اطلاعات استفاده می‌کنیم'),T('We use your details to review the enquiry, arrange the free consultation and discuss appropriate services. The form does not subscribe you to marketing. This site uses no advertising or analytics cookies.','از اطلاعات برای بررسی درخواست، هماهنگی جلسه رایگان و گفت‌وگو درباره خدمات مناسب استفاده می‌کنیم. ارسال فرم شما را عضو فهرست تبلیغاتی نمی‌کند. این سایت از کوکی تبلیغاتی یا تحلیل بازدید استفاده نمی‌کند.')],[T('Your choices','درخواست‌های مربوط به اطلاعات شما'),T('Email reyhaneh.vojoudi@gmail.com to request access, correction or deletion. Enquiry records are kept while the enquiry or agreed support is active; contact us about removal when support ends. Parents or guardians should submit school-student enquiries.','برای دسترسی، اصلاح یا حذف اطلاعات به reyhaneh.vojoudi@gmail.com ایمیل بزنید. اطلاعات تا زمانی که درخواست یا همکاری در جریان است نگهداری می‌شود؛ پس از پایان همکاری می‌توانید برای حذف آن تماس بگیرید. فرم دانش‌آموزان باید توسط والد یا سرپرست ارسال شود.')]]
   out+=section(T('Enquiry privacy notice','حریم خصوصی درخواست مشاوره'),'',rows(items))
  elif p=='terms':out+=section(T('Before we begin','پیش از شروع همکاری'),'',rows([[T('A free first conversation','جلسه اول رایگان'),T('The initial consultation is free. Sending a form does not confirm a booking, admission to a programme or a paid engagement.','مشاوره اولیه رایگان است. ارسال فرم به معنای تأیید جلسه، پذیرش در برنامه یا شروع همکاری مالی نیست.')]]+d['terms'][1:4]+[[T('Agreeing the details','توافق درباره جزئیات'),T('Before paid work begins, we agree the services, educators, schedule, fees, payment and cancellation terms in writing.','پیش از شروع خدمات غیررایگان، درباره نوع خدمات، مدرس‌ها، زمان‌بندی، هزینه، شیوه پرداخت و شرایط لغو به‌صورت کتبی توافق می‌کنیم.')]]))
 if p not in ['contact','privacy','terms']:out+=f'<section class="closing"><div class="wrap"><p class="eyebrow">{T("YOUR NEXT STEP","قدم بعدی شما")}</p><h2>{T("Start with a conversation.","با یک گفت‌وگو شروع کنیم.")}</h2><p>{T("Tell us what you need. Your first online consultation is free.","از نیازتان بگویید. جلسه مشاوره آنلاین اولیه رایگان است.")}</p>{link("contact",cta,l,"button")}</div></section>'
 out+='<footer class="wrap"><div class="footer-top"><div><strong>VELLUM HOUSE</strong><p>'+e(d['footerText'])+'</p></div><div class="footer-links">'+link('journal',d['pages']['journal'],l)+link('contact',cta,l)+link('privacy',d['pages']['privacy'],l)+link('terms',d['pages']['terms'],l)+'</div></div><div class="footer-bottom"><span>© 2026 Vellum House</span><a href="#main">'+e(d['backTop'])+' ↑</a></div></footer></body></html>'
 (R/url(p,l)).write_text(out)
for l in C:
 for p in C[l]['pages']:render(p,l)
(R/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Page not found | Vellum House</title><link rel="stylesheet" href="assets/style.css"><main class="page-hero wrap"><h1>Page not found</h1><p>این صفحه پیدا نشد</p><a href="index.html">English home</a> · <a href="fa.html">صفحه فارسی</a></main></html>')
print('Built 18 bilingual pages + 404')
